    cin>>n>>m;
    map<int,int>mp;
    for(int i=0;i<n;i++){
        int x;
        int sum=0;
        for(int j=0;j<m;j++){
            cin>>x;
            sum+=x;
        }
        mp[sum]++;
        w[i]=sum;
    }
    int pos,sum1,sum;
    for(int i=0;i<n;i++){
        if(mp[w[i]]==1){
            pos=i+1;
            sum=w[i];
        }
        else{
            sum1=w[i];
        }
    }
    int cnt=abs(sum1-sum);
    cout<<pos<<" "<<cnt<<endl;
    return 0;
}
```

